import fs from 'node:fs';import path from 'node:path';import cp from 'node:child_process';import {createRequire} from 'node:module';
const root=process.cwd(),require=createRequire(path.join(root,'apps/api/package.json')),{Client}=require('pg');
const adminUrl=process.env.TALK_TEST_DATABASE_ADMIN_URL,u=new URL(adminUrl);if(u.hostname!=='127.0.0.1'||u.port!=='55439'||u.pathname!=='/postgres')throw Error('Owned endpoint required');
const db=new Client({connectionString:adminUrl});await db.connect();try{const state=(await db.query("SELECT current_setting('data_directory') AS directory")).rows[0];if(state.directory!=='/var/lib/postgresql/data/talk_fixture')throw Error('Owned directory required');if(!(await db.query("SELECT 1 FROM pg_database WHERE datname='messaging_test'")).rowCount)await db.query('CREATE DATABASE messaging_test');}finally{await db.end();}
const url=new URL(adminUrl);url.pathname='/messaging_test';const env={...process.env,DATABASE_URL:url.href,MESSAGING_TEST_DATABASE_URL:url.href};for(const key of Object.keys(env))if(/TOKEN|SECRET|API_KEY/.test(key))delete env[key];
function run(args,options={}){const r=cp.spawnSync('pnpm',args,{cwd:root,env,stdio:'inherit',...options});if(r.status!==0)throw Error('Focused command failed: '+args.slice(0,5).join(' '));}
run(['--filter','@prymeira-talk/api','exec','prisma','migrate','deploy','--schema','prisma/schema.prisma']);
run(['--filter','@prymeira-talk/api','build:prod']);
const suites=['ingress/http-observability.test.ts','ingress/transport.postgres.test.ts','ingress/application.postgres.test.ts','ingress/publication-lease.postgres.test.ts','channels/waha-history-recovery.postgres.test.ts','channels/evolution-history-recovery.postgres.test.ts','channels/history-recovery.audit.postgres.test.ts','messaging/canonical-foundation.postgres.test.ts','messaging/canonical-store.postgres.test.ts','messaging/canonical-reducers.postgres.test.ts'];
let failed=false;const outcomes=[];fs.mkdirSync('validation-artifacts/focused',{recursive:true});
for(const[at,file]of suites.entries()){const output=path.join(root,'validation-artifacts/focused',`${at}.json`),r=cp.spawnSync('pnpm',['exec','vitest','run','src/modules/'+file,'--maxWorkers=1','--fileParallelism=false','--reporter=default','--reporter=json','--outputFile.json='+output],{cwd:path.join(root,'apps/api'),env,stdio:'inherit',timeout:180000});let counts;try{const report=JSON.parse(fs.readFileSync(output));counts={passed:report.numPassedTests,failed:report.numFailedTests,pending:report.numPendingTests,total:report.numTotalTests};}catch{counts={missing:true};}const passed=r.status===0&&counts.total>0&&counts.pending===0&&counts.failed===0;failed||=!passed;outcomes.push({file,exit:r.status,passed,...counts});}
fs.writeFileSync('validation-artifacts/focused/summary.json',JSON.stringify({sha:process.env.GITHUB_SHA,suites:outcomes,allPassed:!failed},null,2));if(failed)process.exitCode=1;
